import{j as H}from"./c-34SCYH7S.js";import{H as L,_ as I,xa as O}from"./c-GQ2L3A4C.js";import{F as i,b as C}from"./c-P5FZWOFE.js";import{x as a}from"./c-PFU5VIIQ.js";import{a as E}from"./c-ZYIGBBBU.js";var N=[{id:"eom",title:"One equation runs the ventilator",level:"Novice",blurb:"PIP, plateau, PEEP, resistance, compliance and the time constant \u2014 from one line of physics.",steps:[{id:"eom1",title:"The equation of motion",setup:{scenario:"normal",settings:{mode:"VC",vt:.45,rr:14,flow:50,pattern:"square",pause:0,peep:5},view:"front"},focus:["lungs"],say:"Every pressure on a ventilator screen comes from one equation. Airway pressure equals resistance times flow, plus volume divided by compliance, plus PEEP. The ventilator is pushing gas through a tube and a tree of airways, and stretching an elastic lung that already sits at PEEP. Watch the lungs: each breath, the bases move down with the diaphragm."},{id:"eom2",title:"Square flow, rising pressure",focus:["pressure","flow"],say:"In volume control with a square wave, flow is constant during inspiration. Look at the pressure trace. It jumps up the instant flow starts. That jump is resistance times flow. After the jump, pressure keeps climbing in a straight line, because as volume goes in, the elastic lung pushes back harder. The top of that climb is the peak inspiratory pressure, PIP."},{id:"eom3",title:"Stop the flow: plateau",setup:{hold:"i"},focus:["pressure","numbers"],say:"Now an inspiratory hold. The valves close and flow drops to zero. With no flow, the resistance term disappears, so the pressure falls from the peak to a plateau. What is left is purely elastic: how hard the stretched lung and chest wall are pushing back. That is the plateau pressure. The drop from peak to plateau tells you about the airways. The plateau tells you about the lung."},{id:"eom4",title:"Driving pressure and compliance",focus:["numbers"],say:"Plateau minus PEEP is the driving pressure. It is the pressure needed to fit this tidal volume into this lung. Divide the tidal volume by the driving pressure and you get static compliance. Normal is about sixty to eighty milliliters per centimeter of water. The coloured bar under the numbers splits the peak pressure into its three parts: PEEP, elastic, and resistive."},{id:"eom5",title:"Passive exhalation and tau",focus:["flow","volume"],say:"Expiration is passive. The lung empties like a spring through a narrow tube, so flow is highest at the start and decays exponentially. The time constant, tau, is resistance times compliance. After one tau, about sixty three percent of the breath is out. After three tau, about ninety five percent. Here tau is under half a second, so the lung is empty long before the next breath."}]},{id:"rc",title:"Resistance or compliance?",level:"Novice",blurb:"The high-pressure alarm, solved with one inspiratory hold.",steps:[{id:"rc1",title:"Narrow airways",setup:{scenario:"asthma",settings:{rr:12,pause:.4},view:"airway"},focus:["pressure","lungs"],say:"This is severe bronchospasm. The airways in the translucent lungs are narrowed and inflamed. Look at the pressure: the peak is high, but the plateau after the pause is almost normal. The gap between them is huge. Resistance has gone up, compliance has not. The pressure is being spent pushing gas through the airways, not stretching the alveoli."},{id:"rc2",title:"Open the airways",setup:{act:"bronchodilator"},focus:["pressure","lungs","numbers"],say:"A bronchodilator relaxes the smooth muscle. Airway resistance depends on the fourth power of the radius, so a small increase in calibre makes a large drop in resistance. Watch the airways widen, and the peak pressure fall toward the plateau. Time is compressed here: fifteen minutes of drug effect in about fifteen seconds."},{id:"rc3",title:"A stiff lung",setup:{scenario:"ards",settings:{pause:.4,rr:16},view:"side"},focus:["pressure","numbers"],say:"Now a stiff, injured lung. Peak and plateau have both risen, and the gap between them is normal. The same tidal volume needs much more pressure to fit, because a large part of the lung is collapsed and the rest is stiff. That is a compliance problem."},{id:"rc4",title:"The rule",focus:["numbers"],say:"So, when the high-pressure alarm sounds, do an inspiratory hold. High peak with a normal plateau means resistance: kinked or bitten tube, secretions, bronchospasm. High peak with a high plateau means compliance: pneumothorax, mainstem intubation, pulmonary oedema, abdominal distension, or a stiff chest wall."}]},{id:"vcpc",title:"Volume control vs pressure control",level:"Intermediate",blurb:"What you set, and what you get.",steps:[{id:"vp1",title:"Volume control",setup:{scenario:"normal",settings:{mode:"VC",vt:.45,rr:14,flow:50,pattern:"square",pause:0},view:"front"},focus:["pressure","flow","volume"],say:"In volume control you choose the tidal volume and the flow. The ventilator guarantees them, and pressure is whatever it takes. If the lung gets stiffer, or the airway narrows, pressure rises. That protects minute ventilation, but you must watch the pressures."},{id:"vp2",title:"Pressure control",setup:{settings:{mode:"PC",pinsp:13,ti:1}},focus:["pressure","flow","volume"],say:"In pressure control you choose the pressure above PEEP and the inspiratory time. The pressure trace is now a square. Flow is high at first, then decays as the lung fills and the pressure difference shrinks. Tidal volume is the result. Here it is similar to before."},{id:"vp3",title:"Make the lung stiff",setup:{scenario:"ards",settings:{mode:"PC",pinsp:13,ti:1,rr:14,peep:5},view:"side"},focus:["volume","numbers"],say:"Same pressure control settings, but now in a stiff ARDS lung. The pressure is capped, so the volume falls. Look at the tidal volume: much smaller. In pressure modes, a falling tidal volume is your warning sign, just as a rising pressure is in volume modes."},{id:"vp4",title:"Decelerating flow",setup:{settings:{mode:"VC",vt:.42,rr:18,flow:60,pattern:"decel"}},focus:["flow","pressure"],say:"Volume control can also use a decelerating flow pattern. It delivers the volume with a lower peak pressure and a more even distribution between fast and slow lung units. The plateau does not change, because the volume and the lung are the same."}]},{id:"peep",title:"PEEP, recruitment and overdistension",level:"Intermediate",blurb:"Open the lung, keep it open \u2014 and know when to stop.",steps:[{id:"pe1",title:"The collapsed, dependent lung",setup:{scenario:"ards",settings:{mode:"VC",vt:.42,rr:22,peep:5,flow:60,pattern:"square",pause:.3},view:"side"},focus:["lungs","gas"],say:"This patient lies on their back. In ARDS, the heavy, wet lung collapses under its own weight, so the posterior, dependent regions are dark and airless. Blood still flows past them, but it picks up no oxygen. That is shunt, and it is why this patient is hypoxic despite a high FiO\u2082."},{id:"pe2",title:"Raise PEEP",setup:{settings:{peep:14}},focus:["lungs","loops","gas"],say:"Now raise PEEP to fourteen. Collapsed units need a higher pressure to open than to stay open. As PEEP rises, the dark posterior lung turns pink: those units are recruited. The same tidal volume now goes into more alveoli, so the driving pressure falls and compliance improves. Watch the oxygen saturation climb as shunt falls."},{id:"pe3",title:"Too much",setup:{settings:{peep:22,vt:.42}},focus:["lungs","loops","numbers","gas"],say:"Now PEEP twenty two. The anterior lung, which was already open, turns pale: it is over-stretched. The pressure volume loop flattens at the top, compliance falls again, and the plateau is above thirty. High intrathoracic pressure also squeezes the great veins, so venous return and blood pressure fall. More PEEP is not always better."},{id:"pe4",title:"Find the middle",setup:{settings:{peep:14,vt:.42},ff:30},focus:["numbers","gas"],say:"The best PEEP opens the collapsed lung without over-stretching the open lung. At the bedside we look for the lowest driving pressure, an acceptable plateau, and oxygenation, while watching blood pressure. Try it yourself in explore mode."}]},{id:"auto",title:"Auto-PEEP and the time constant",level:"Intermediate",blurb:"Why obstructed lungs need time to empty.",steps:[{id:"au1",title:"Flow that never reaches zero",setup:{scenario:"asthma",settings:{mode:"VC",vt:.5,rr:24,flow:50,pattern:"square",pause:0},view:"airway"},focus:["flow","lungs"],say:"In severe asthma the time constant is long. Look at the expiratory flow: it is still negative when the next breath begins. The lung has not finished emptying. Each breath leaves a little gas behind, until the lung sits at a higher volume. That trapped gas has pressure: intrinsic PEEP, or auto-PEEP."},{id:"au2",title:"Measure it",setup:{hold:"e"},focus:["pressure","numbers"],say:"An expiratory hold closes the valves at the end of expiration. The trapped alveolar pressure equilibrates with the airway, and the pressure rises above set PEEP. The difference is auto-PEEP. It adds to plateau pressure, compresses the heart, and makes the patient work harder to trigger."},{id:"au3",title:"Give it time",setup:{settings:{rr:12,flow:80}},focus:["flow","volume","numbers"],say:"The most powerful fix is expiratory time. Lower the rate, and shorten inspiration with a higher flow. Now expiratory flow reaches zero before the next breath, and the auto-PEEP disappears. Carbon dioxide may rise. In asthma that is usually accepted: permissive hypercapnia."}]},{id:"sync",title:"Triggering, cycling and dyssynchrony",level:"Advanced",blurb:"Reading the patient through the ventilator.",steps:[{id:"sy1",title:"Pressure support",setup:{scenario:"normal",dyss:null,settings:{mode:"PSV",ps:10,peep:5,cyclePct:25,trigFlow:2},view:"front",pmus:!0},focus:["pressure","flow"],say:"In pressure support the patient starts every breath. The red dashed line is the patient\u2019s own muscle effort, which the ventilator cannot see directly. When the effort pulls enough flow past the trigger threshold, the ventilator delivers a set pressure. It stops when flow has fallen to a set percentage of the peak flow: the cycle-off criterion."},{id:"sy2",title:"Premature cycling",setup:{dyss:"premature",scenario:"normal",settings:{mode:"PSV",ps:14,cyclePct:60},pmus:!0},focus:["flow","pressure"],say:"Here the cycle-off threshold is sixty percent. The breath ends while the red effort line is still rising: the patient is still inhaling, but the ventilator has stopped. Look for the dip in expiratory flow right after cycling, and sometimes a second breath."},{id:"sy3",title:"Delayed cycling",setup:{dyss:"delayed",scenario:"copd",settings:{mode:"PSV",ps:14,cyclePct:5},pmus:!0},focus:["flow","pressure"],say:"In COPD the flow decays slowly. With a cycle-off of five percent, the ventilator keeps inflating long after the patient has finished. The effort line goes negative: the patient is actively pushing to exhale against the machine. Raising the cycle-off percentage fixes it."},{id:"sy4",title:"Ineffective efforts",setup:{dyss:"ineffective",scenario:"copd",pmus:!0},focus:["flow"],say:"Now watch the expiratory flow between breaths. Small upward bumps appear with each red effort, but no breath follows. Trapped gas means the patient must first overcome auto-PEEP before any flow reaches the sensor. These are ineffective efforts. Try the challenges to diagnose and fix each dyssynchrony yourself."}]}];var D=[{id:"o2path",title:"Oxygen: from air to mitochondria",level:"Novice",blurb:"Alveolar gas, loading in the capillary, delivery, extraction \u2014 and why anaemia does not lower SpO\u2082.",steps:[{id:"ox1",title:"Fresh gas in the alveolus",setup:{preset:"normal",station:"lung"},say:"Room air is twenty one percent oxygen. By the time it is warmed, humidified and mixed with carbon dioxide in the alveoli, the alveolar oxygen pressure is about one hundred. The alveolar gas equation says it: FiO\u2082 times seven hundred and thirteen, minus PaCO\u2082 divided by zero point eight."},{id:"ox2",title:"Blood arrives venous",setup:{station:"alveolus"},say:"Here is one alveolar sac and its capillary basket, drawn to scale. Blood arrives from the pulmonary artery dark, about seventy percent saturated. It spreads over the alveoli in a single layer of red cells, separated from the air by a barrier thinner than one micrometre. It leaves bright red, about ninety seven percent saturated, through the pulmonary venule."},{id:"ox3",title:"Loading in the first third",setup:{station:"capillary"},say:"Zoom in to a single capillary. Red cells squeeze through one at a time. They take about three quarters of a second to cross, but they are fully loaded in the first third of that time. That reserve is why a healthy person can exercise without desaturating."},{id:"ox4",title:"Delivery and extraction",setup:{station:"tissue"},say:"In the muscle, arterial blood gives up oxygen to the mitochondria and picks up carbon dioxide. Oxygen delivery is arterial content times cardiac output: about a thousand millilitres a minute. The tissues use about a quarter of it, so venous blood returns about seventy five percent saturated."},{id:"ox5",title:"Anaemia: normal SpO\u2082, empty blood",setup:{knobs:{hb:6.5},station:"tissue",ff:20},say:"Now drop the haemoglobin to six and a half. Look at the arterial gas: PaO\u2082 and saturation are unchanged, and the pulse oximeter still reads normal. But oxygen content has halved, because content is one point three four times haemoglobin times saturation, plus a tiny dissolved fraction. The tissues must extract more, so venous saturation falls. SpO\u2082 tells you how full each lorry is, not how many lorries there are."}]},{id:"hypox",title:"Why is the PaO\u2082 low?",level:"Intermediate",blurb:"Hypoventilation, V/Q mismatch, shunt, dead space \u2014 and which ones oxygen fixes.",steps:[{id:"hy1",title:"Hypoventilation",setup:{preset:"normal",knobs:{drive:.35},station:"lung",ff:30},say:"First, hypoventilation. Depress the drive, as an opioid would. Less fresh gas reaches the alveoli, so carbon dioxide builds up and, by the alveolar gas equation, alveolar oxygen falls. The lungs themselves are normal, so the A to a gradient stays normal. A little oxygen, or simply more ventilation, fixes it."},{id:"hy2",title:"V/Q mismatch",setup:{preset:"normal",knobs:{lowVQ:.35},station:"alveolus",ff:20},say:"Now V Q mismatch. Some alveoli get plenty of blood but little air. Blood leaving them is poorly oxygenated, and the A to a gradient widens. This is the commonest cause of hypoxaemia: pneumonia, COPD, asthma, pulmonary embolism."},{id:"hy3",title:"Oxygen fixes V/Q mismatch",setup:{knobs:{fio2:.4},ff:10},say:"Raise the FiO\u2082 to forty percent. Even poorly ventilated alveoli eventually fill with oxygen-rich gas, so their blood saturates and the PaO\u2082 rises a lot. V Q mismatch is oxygen responsive."},{id:"hy4",title:"Shunt does not respond",setup:{preset:"normal",knobs:{shunt:.35,fio2:1},station:"alveolus",ff:10},say:"Now shunt: blood passing collapsed or flooded alveoli that receive no gas at all. The dark alveoli are airless, and the blood through them stays venous. Even at one hundred percent oxygen, the PaO\u2082 barely rises, because extra oxygen never reaches that blood. Shunt needs the alveoli reopened: PEEP, recruitment, treating the cause."},{id:"hy5",title:"Dead space",setup:{preset:"normal",knobs:{vdAlv:.45,shunt:.03,fio2:.21},station:"alveolus",ff:30},say:"Finally, dead space: alveoli that are ventilated but not perfused, shown with grey empty capillaries. They waste ventilation, so carbon dioxide clearance falls and the gap between PaCO\u2082 and end tidal CO\u2082 widens. Pulmonary embolism, low cardiac output and over-distension all do this."}]},{id:"resp",title:"CO\u2082, pH and the kidneys",level:"Intermediate",blurb:"Acute and chronic respiratory acidosis, and what happens 48 hours later.",steps:[{id:"rs1",title:"Acute respiratory acidosis",setup:{preset:"opioid",station:"tissue"},say:"This patient has taken an opioid. Carbon dioxide has risen to the eighties, and the pH has fallen quickly. Carbon dioxide combines with water to form carbonic acid, which releases hydrogen ions. Haemoglobin and proteins buffer some of them, so bicarbonate rises only about one per ten millimetres of mercury. That is acute compensation."},{id:"rs2",title:"The acid\u2013base map",setup:{station:"kidney"},say:"Look at the acid base map. The dot sits in the acute respiratory acidosis band. Now we will keep the ventilation the same and let two days pass."},{id:"rs3",title:"48 hours later",setup:{station:"kidney",ff:2880},say:"The kidneys have been excreting acid as ammonium and reclaiming and making new bicarbonate. Bicarbonate has risen by about three and a half per ten millimetres of mercury, and the pH is back near normal, even though the CO\u2082 has not changed. The dot has moved along its path into the chronic band. This is why a COPD patient can live with a PaCO\u2082 of sixty."},{id:"rs4",title:"Post-hypercapnic alkalosis",setup:{drug:"naloxone",station:"lung",ff:30},say:"Now reverse the opioid. Ventilation returns, and CO\u2082 falls within minutes. But the kidneys need days to give back the extra bicarbonate, so the patient becomes alkalaemic. The same thing happens when a chronic retainer is over-ventilated on a ventilator."}]},{id:"metab",title:"Metabolic acidosis and the anion gap",level:"Advanced",blurb:"DKA, lactate, salicylate: the gap, Winter\u2019s formula and mixed disorders.",steps:[{id:"mt1",title:"Ketoacids consume bicarbonate",setup:{preset:"dka",station:"tissue"},say:"Diabetic ketoacidosis. Ketoacids release hydrogen ions, and bicarbonate is used up buffering them. The ketone anions stay behind, unmeasured, so the anion gap, sodium minus chloride plus bicarbonate, widens. This is a high anion gap metabolic acidosis."},{id:"mt2",title:"The lungs compensate",setup:{station:"lung"},say:"The low pH drives deep, fast breathing, Kussmaul respiration. Winter\u2019s formula predicts the expected PaCO\u2082: one and a half times bicarbonate plus eight, plus or minus two. If the measured CO\u2082 is higher, the patient is tiring or sedated: a second, respiratory, problem."},{id:"mt3",title:"Lactate",setup:{preset:"sepsis",station:"tissue"},say:"In septic shock, lactate rises. Some comes from tissues short of oxygen, shown in magenta, but much comes from adrenaline-driven glycolysis and from a liver too poorly perfused to clear it. Lactate is a marker of stress and clearance, not simply of oxygen debt."},{id:"mt4",title:"A mixed disorder",setup:{preset:"salicylate",station:"lung"},say:"Salicylate poisoning stimulates the respiratory centre directly, causing a respiratory alkalosis, and uncouples oxidative phosphorylation, adding organic acid. The CO\u2082 is lower than Winter\u2019s formula predicts. Two primary disorders at once. The low CO\u2082 is protecting the patient: if they are intubated, it must stay low."}]},{id:"vbg",title:"ABG or VBG?",level:"Novice",blurb:"Two different samples, two different questions.",steps:[{id:"vb1",title:"Two sampling sites",setup:{preset:"normal",station:"tissue"},say:"An arterial gas samples blood on its way to the tissues. A venous gas samples blood that has already given up oxygen and collected carbon dioxide. In a stable patient, venous pH is about zero point zero three lower and venous CO\u2082 about five higher. Bicarbonate and lactate are almost the same."},{id:"vb2",title:"Venous PO\u2082 is not oxygenation",setup:{station:"tissue"},say:"Venous PO\u2082 tells you only what the tissues left behind. A venous PO\u2082 of forty is normal, not hypoxaemia. To judge oxygenation, use the pulse oximeter or an arterial sample. The app always shows these two samples separately for that reason."},{id:"vb3",title:"When they diverge",setup:{preset:"arrest",station:"tissue"},say:"During cardiac arrest with CPR, blood flow is so low that carbon dioxide piles up in the tissues. Venous CO\u2082 is far higher than arterial, and the venous pH far lower. When flow is poor, a venous gas no longer mirrors the arterial one."}]}];var V=[{id:"hyperk",title:"Hyperkalaemia: stabilise, shift, remove",level:"Intermediate",blurb:"Why calcium works without touching the potassium.",steps:[{id:"hk1",title:"Potassium lives inside cells",setup:{reset:!0,lab:"k",values:{k:4.2},view:"cell",renal:.1},say:"Almost all the body\u2019s potassium is inside cells, about one hundred and forty inside against four outside. The sodium potassium pump in the membrane keeps it that way. That steep ratio sets the resting membrane potential of every heart cell, about minus eighty five millivolts."},{id:"hk2",title:"Raise the outside potassium",setup:{values:{k:7.4}},say:"Now the kidneys have failed and plasma potassium is seven point four. The ratio across the membrane falls, so the resting potential rises toward the threshold. Look at the gap on the membrane gauge: it has shrunk. The ECG shows peaked T waves, flattened P waves and a widening QRS. The heart is close to an arrhythmia."},{id:"hk3",title:"Step one: calcium",setup:{drug:"calcium",ff:3},say:"Give intravenous calcium. Watch the numbers carefully: the potassium has not changed at all. What changed is the threshold. Calcium moves the threshold potential up, away from the resting potential, and restores the safety gap. The QRS narrows within minutes. Calcium buys time: thirty to sixty minutes."},{id:"hk4",title:"Step two: shift it into cells",setup:{drug:"insulin",ff:40},say:"Now insulin with dextrose. Insulin switches on the sodium potassium pump, so potassium moves from the blood back into the cells. Plasma potassium falls by around one. Nebulised salbutamol does the same through beta two receptors. But nothing has left the body."},{id:"hk5",title:"The rebound",setup:{ff:300},say:"Five hours later the insulin has worn off, the pumps have slowed, and potassium has leaked back out. This is the rebound. Shifting treatments are temporary. The potassium must be removed."},{id:"hk6",title:"Step three: remove it",setup:{drug:"dialysis",ff:240},say:"Dialysis removes potassium from the body, and so do binders, and diuretics if the kidneys work. Stabilise, shift, remove: in that order, and repeat the ECG and the potassium."}]},{id:"hypona",title:"Hyponatraemia and the brain",level:"Intermediate",blurb:"Cell swelling, adaptation, and why speed of correction matters.",steps:[{id:"hn1",title:"Water follows solute",setup:{reset:!0,lab:"na",values:{na:140},view:"cell",naMode:"acute"},say:"Sodium is the main solute outside cells. Cell membranes let water through freely, so water moves until the concentration inside and outside is equal. Plasma sodium therefore sets the size of every cell, and the brain is the one organ that has no room to swell."},{id:"hn2",title:"Acute hyponatraemia",setup:{values:{na:118}},say:"Drop the sodium to one hundred and eighteen over a few hours, as happens with water intoxication or after surgery. Water rushes into brain cells and they swell. Inside the skull, that means headache, vomiting, seizures and eventually herniation. This is an emergency: a small bolus of hypertonic saline, raising the sodium by four to six, pulls water back out."},{id:"hn3",title:"The brain adapts",setup:{naMode:"chronic",values:{na:118},ff:2880},say:"If the sodium falls slowly, over days, brain cells export their own solutes, organic osmolytes, and shrink back to a normal size. This patient has the same sodium of one hundred and eighteen, but the brain cells are no longer swollen."},{id:"hn4",title:"Correcting too fast",setup:{correct:134},say:"Now correct that chronic hyponatraemia too quickly: sixteen in a day. The adapted brain cells cannot re-import their osmolytes fast enough, water is pulled out, and the myelin of the pons can be destroyed. Osmotic demyelination appears days later and may be permanent. Limit correction to about eight to ten in twenty four hours."}]},{id:"anaemia",title:"Anaemia: the oximeter cannot see it",level:"Novice",blurb:"Saturation versus content.",steps:[{id:"an1",title:"Normal blood",setup:{reset:!0,lab:"hb",values:{hb:14},view:"cell"},say:"Here is a capillary full of red cells. Each one is packed with haemoglobin, and each haemoglobin is ninety seven percent saturated with oxygen. Oxygen content is about nineteen millilitres in every decilitre of blood."},{id:"an2",title:"Half the red cells",setup:{values:{hb:6.5}},say:"Now the haemoglobin is six and a half. There are half as many red cells, but each one is still fully saturated, so the pulse oximeter still reads ninety seven percent. The oxygen content has halved. The heart pumps faster to compensate and the tissues extract more, so venous saturation falls."},{id:"an3",title:"Treat the content",setup:{drug:"transfusion"},say:"A unit of red cells raises the haemoglobin by about one gram per decilitre and restores content. Remember: a normal SpO\u2082 says the haemoglobin present is full, not that there is enough of it."}]},{id:"lactate",title:"Lactate: made and cleared",level:"Intermediate",blurb:"Why lactate rises \u2014 and why it falls.",steps:[{id:"lc1",title:"A balance",setup:{reset:!0,lab:"lac",view:"cell"},say:"Every cell makes some lactate, and the liver and kidneys clear it. A normal level of about one simply means production and clearance are matched."},{id:"lc2",title:"Shock",setup:{values:{},ff:90},say:"Now cardiac output falls in shock. Tissues short of oxygen turn more glucose into lactate, and a poorly perfused liver clears less. Lactate climbs. Adrenaline and sepsis raise it further, even when oxygen delivery is adequate, by speeding glycolysis."},{id:"lc3",title:"Resuscitation",setup:{ff:180},say:"Restore perfusion and the balance reverses. Lactate falls over hours, as the liver clears it. A falling lactate is one of the best signs that resuscitation is working."}]}];var R=[{id:"ln-setup",title:"From artery to monitor",level:"Novice",blurb:"What an arterial line and a central line actually are, and where the numbers come from.",steps:[{id:"ln-setup-1",title:"A column of saline carries the pressure",say:"An arterial line is a short cannula in an artery \u2014 here the right radial \u2014 joined by stiff, saline-filled tubing to a pressure transducer. The fluid column transmits every pressure change to the transducer, which turns it into the waveform and the numbers on the monitor.",do:{scenario:"normal",view:"bed"}},{id:"ln-setup-2",title:"The radial cannula",say:"A 20-gauge cannula sits in the radial artery at the wrist. A bag of saline squeezed to 300 mmHg pushes about 3 mL an hour through the line, so blood cannot back up and clot. The bag must stay above the patient\u2019s systolic pressure.",do:{view:"wrist"}},{id:"ln-setup-3",title:"The central line",say:"The central venous catheter enters the right internal jugular vein and runs down through the superior vena cava. Its tip should sit at the cavo-atrial junction, where the SVC meets the right atrium. The pressure there is the central venous pressure \u2014 essentially right-atrial pressure.",do:{view:"neck"}},{id:"ln-setup-4",title:"Inside the chest",say:"Watch the chambers. The atria contract just after each P wave, the ventricles after each QRS. The right atrium glows brighter as its pressure rises, and a pulse wave runs from the aorta to the wrist \u2014 it arrives about a tenth of a second after the heart ejects.",do:{view:"heart"}},{id:"ln-setup-5",title:"One reference level for everything",say:"All the pressures are measured against one reference point: the phlebostatic axis \u2014 the fourth intercostal space in the mid-axillary line, roughly the level of the right atrium. The transducer\u2019s air\u2013fluid interface, the zeroing stopcock, must sit level with it.",do:{view:"level"}}]},{id:"ln-art",title:"Reading the arterial waveform",level:"Novice",blurb:"Upstroke, systolic peak, dicrotic notch, diastolic run-off \u2014 and why MAP is the number to trust.",steps:[{id:"ln-art-1",title:"Each beat, drawn",say:"The steep upstroke is the left ventricle ejecting into the aorta. The rounded top is the systolic peak. As ejection ends the aortic valve snaps shut, making the dicrotic notch. Then pressure runs off through the arterioles until the next beat: that low point is the diastolic pressure.",do:{scenario:"normal",view:"bed"}},{id:"ln-art-2",title:"Wrist versus aorta",say:"The radial systolic peak is taller and spikier than in the central aorta and diastolic slightly lower, so the pulse pressure is wider \u2014 the wave steepens as it travels out to smaller, stiffer arteries. The mean pressure hardly changes, which is one reason MAP is the number to trust for decisions. Compare the columns in the table: radial versus central aorta.",do:{showTrue:!0}},{id:"ln-art-3",title:"A low dicrotic notch",say:"This patient is in vasodilated septic shock. Resistance is so low that blood runs off before the valve even closes: the notch slides down toward the diastolic level, diastolic pressure falls and MAP is below 65.",do:{scenario:"sepsis"}},{id:"ln-art-4",title:"Vasopressor effect",say:"Norepinephrine restores vascular tone. Watch diastolic pressure and MAP climb and the notch rise back up the downstroke.",do:{nore:.1}},{id:"ln-art-5",title:"Stiff arteries",say:"An older, hypertensive patient: the stiff aorta cannot stretch to absorb each stroke, and the reflected wave returns early, during systole. Systolic pressure climbs, diastolic falls, and the pulse pressure widens past 60 mmHg \u2014 with a late systolic shoulder.",do:{scenario:"stiff"}}]},{id:"ln-cvp",title:"Reading the CVP waveform",level:"Intermediate",blurb:"a, c, x, v, y \u2014 lined up against the ECG \u2014 and reading the number at end-expiration.",steps:[{id:"ln-cvp-1",title:"Three peaks, two descents",say:"The a wave follows the P wave: the atrium contracts. The small c wave comes just after the QRS, as the closing tricuspid valve bulges back into the atrium. The x descent is the atrium relaxing and the valve ring being pulled down. The v wave is the atrium filling against the closed valve, near the end of the T wave. The y descent is the valve opening and blood rushing into the ventricle.",do:{scenario:"normal",view:"heart"}},{id:"ln-cvp-2",title:"Breathing moves the whole trace",say:"The shaded bands are breaths in. Breathing spontaneously, each breath in lowers the pressure in the chest, so the whole CVP trace dips. The monitor\u2019s number averages every phase, so it reads a little low.",do:{vent:"spont"}},{id:"ln-cvp-3",title:"Measure it yourself",say:"The monitor is frozen. Drag across the CVP trace and read the pressure at end-expiration \u2014 just before a shaded breath begins \u2014 at the base of the c wave. That is the value to record. Compare it with the monitor\u2019s mean.",do:{freeze:!0}},{id:"ln-cvp-4",title:"On the ventilator it flips",say:"With positive-pressure ventilation, inspiration raises the pressure in the chest, so the CVP rises with each breath. End-expiration is now the lowest part of the respiratory cycle \u2014 still just before the next breath. The rule stays the same: read at end-expiration.",do:{vent:"ppv"}},{id:"ln-cvp-5",title:"Cannon a waves",say:"Complete heart block: atria and ventricles beat independently. When the atrium happens to contract while the tricuspid valve is shut, the blood is pushed back up the jugular: a giant cannon a wave.",do:{scenario:"chb"}},{id:"ln-cvp-6",title:"No a wave in AF",say:"Atrial fibrillation: the atria quiver and never contract as one, so the a wave disappears. You see only c and v, and the arterial pulse varies with every irregular R-R interval.",do:{scenario:"af"}},{id:"ln-cvp-7",title:"Giant c-v waves",say:"Severe tricuspid regurgitation: the right ventricle pumps backwards into the atrium in every systole. The x descent is filled in by a giant c-v wave that can look almost like a ventricular trace.",do:{scenario:"tr"}}]},{id:"ln-level",title:"Levelling and zeroing",level:"Novice",blurb:"Two different jobs: levelling fixes the reference height, zeroing removes atmospheric pressure.",steps:[{id:"ln-level-1",title:"Levelled",say:"The transducers are level with the phlebostatic axis. Levelling and zeroing are different jobs: levelling sets the reference height; zeroing tells the monitor what atmospheric pressure reads.",do:{scenario:"normal",view:"level",showTrue:!0}},{id:"ln-level-2",title:"Ten centimetres too low",say:"The transducer has slipped 10 cm below the axis. The extra 10 cm of saline adds 10 \xD7 0.74 = 7.4 mmHg to every reading. An arterial MAP of 95 becomes 102 \u2014 but a CVP of 5 becomes 12, more than double. Low transducer, high reading.",do:{below:10}},{id:"ln-level-3",title:"Raising the head of the bed",say:"The line was levelled with the bed flat. Now the head of the bed goes up to 30 degrees: the chest \u2014 and the phlebostatic axis \u2014 rises about 27 cm, but the transducer on the pole stays where it was. Every pressure now reads about 20 mmHg high. Re-level after any change in bed height or position.",do:{hob:30,fromHob:0}},{id:"ln-level-4",title:"Zero to air",say:"Zeroing: turn the stopcock off to the patient and open to air, press zero, then turn it back. The monitor now knows what atmospheric pressure looks like at the level of the stopcock.",do:{below:0,hob:30}},{id:"ln-level-5",title:"The classic mistake",say:"This line was zeroed while the stopcock was still open to the patient. The monitor subtracted the patient\u2019s own pressure: the trace sits around zero and swings negative. The shape is right; the numbers are wrong. Zero again, open to air.",do:{zeroWrong:"art"}}]},{id:"ln-damp",title:"Damping and the square-wave test",level:"Intermediate",blurb:"Why a line rings or smears, and how a one-second flush tells you which.",steps:[{id:"ln-damp-1",title:"An optimally damped line",say:"Pull the flush for a second and let go. The trace jumps to the bag pressure, drops back, bounces one and a half to two times, then the waveform resumes. That is an optimally damped system: trust the systolic and diastolic values.",do:{scenario:"normal",flush:"art",showTrue:!0}},{id:"ln-damp-2",title:"Underdamped: it rings",say:"Extra extension tubing and stopcocks lower the natural frequency of the line. Now the flush bounces many times, and each heartbeat sets the line ringing: a spiky systolic overshoot. Systolic reads too high, diastolic slightly low \u2014 MAP is the least affected. It gets worse at faster heart rates.",do:{art:"longTubing",flush:"art",showTrue:!0}},{id:"ln-damp-3",title:"A small bubble does the same",say:"A tiny air bubble is very compliant. It drops the natural frequency sharply, so the line resonates and overshoots. Turn the stopcock off to the patient and flush the bubble out through the side port to waste.",do:{art:"smallBubble",flush:"art",showTrue:!0}},{id:"ln-damp-4",title:"Overdamped: it smears",say:"A clot at the tip, a kink, a large bubble or a soft pressure bag absorbs the pulse. The flush slides back with no bounce, the notch disappears, systolic reads low and diastolic high. MAP still holds \u2014 until the line blocks completely.",do:{art:"clot",flush:"art",showTrue:!0}},{id:"ln-damp-5",title:"Never flush a clot forward",say:"An overdamped arterial line with sluggish blood return: aspirate first, then flush. Flushing a clot forward can embolise into the hand; flushing a bubble toward the patient puts air into the circulation \u2014 from a radial line it can even travel back up to the brain. Always clear air out of the side port to waste.",do:{art:"clot",view:"wrist"}}]},{id:"ln-heartlung",title:"Heart\u2013lung interactions",level:"Advanced",blurb:"Pulse-pressure variation, fluid responsiveness and pulsus paradoxus.",steps:[{id:"ln-hl-1",title:"Pulse-pressure variation",say:"This patient has lost blood and is on the ventilator. Each positive-pressure breath squeezes blood out of the lungs into the left heart, then limits venous return for the next few beats. An underfilled heart is sensitive to that: the pulse pressure swings by more than 13 %.",do:{scenario:"hypovol",vent:"ppv",vt:8}},{id:"ln-hl-2",title:"Give fluid, watch PPV fall",say:"Three 500 mL boluses. Stroke volume rises, the heart moves up the steep part of its Starling curve onto the flat part, and the variation shrinks. The patient was fluid-responsive.",do:{fluids:3}},{id:"ln-hl-3",title:"When PPV lies",say:"PPV only predicts fluid response with controlled breaths of at least 8 mL/kg, a regular rhythm, no spontaneous effort and a closed chest \u2014 and it is unreliable with very stiff lungs, RV failure or raised abdominal pressure. Here the patient breathes on their own: the variation is meaningless.",do:{scenario:"hypovol",vent:"spont"}},{id:"ln-hl-4",title:"Irregular rhythm",say:"In atrial fibrillation every beat has a different filling time, so pulse pressure varies whatever the volume status. PPV cannot be used.",do:{scenario:"af",vent:"ppv"}},{id:"ln-hl-5",title:"Pulsus paradoxus",say:"Cardiac tamponade, breathing spontaneously. The pericardium limits total heart volume: when the right heart fills on inspiration, the septum bows left and the left ventricle ejects less. Systolic pressure falls more than 10 mmHg with every breath in, the CVP is high, and there is no y descent.",do:{scenario:"tamponade",vent:"spont"}},{id:"ln-hl-6",title:"Drain it",say:"Pericardiocentesis. As the fluid comes off, the paradox disappears, the CVP falls, the y descent returns and the heart rate slows.",do:{tap:!0}}]},{id:"ln-disease",title:"Waveforms of disease",level:"Intermediate",blurb:"Aortic stenosis and regurgitation, LV failure, PVCs, RV failure.",steps:[{id:"ln-dz-1",title:"Aortic stenosis",say:"A narrow valve slows ejection: the upstroke is slow and late (pulsus tardus), the peak small (parvus), often with an anacrotic shoulder, and the notch is faint.",do:{scenario:"as"}},{id:"ln-dz-2",title:"Aortic regurgitation",say:"Blood falls back into the ventricle in diastole: diastolic pressure is very low, and the ventricle ejects a huge stroke \u2014 a steep upstroke, a wide pulse pressure, often a double systolic peak, and no notch.",do:{scenario:"ar"}},{id:"ln-dz-3",title:"Failing left ventricle",say:"Cardiogenic shock: a weak ventricle ejects slowly against high resistance. The upstroke is sluggish, the pulse pressure narrow, and the CVP high. Little pulse-pressure variation: more fluid will not help.",do:{scenario:"cardiogenic",vent:"ppv"}},{id:"ln-dz-4",title:"PVCs",say:"A premature beat fires before the ventricle has filled: a small or absent pulse. The pause that follows lets the next beat fill more, and it is bigger than normal.",do:{scenario:"pvc"}},{id:"ln-dz-5",title:"Right ventricular failure",say:"Massive pulmonary embolism: the right ventricle is pressure-loaded. The CVP is high with large a and v waves, the left heart is underfilled and the arterial pulse is narrow.",do:{scenario:"rvfail"}}]}];var p={suction:!1,suctionSet:20,source:.4,leak:0,leakSource:"patient",kink:!1,clot:!1,clamped:!1,loopMl:0,unitHigh:!1,sideHoleOut:!1,expanded:.6,fluid:"serous",initialMl:150,rateMlH:20,hours:2,ppv:!0},J=e=>Math.max(0,Math.min(1,e));function ce(e,t){let s=e.kink||e.clot||e.clamped,u=e.loopMl>0?Math.min(20,e.loopMl/6):0,n=!s,v=Math.max(0,t.hi-t.lo),w=(t.hi+t.lo)/2,U=.1+.9*(1-J(e.expanded)),k=n?U*(e.suction?.3:1)*(u>0?.35:1):0,f=+(v*k).toFixed(1),$=+(-(t.p-w)*k).toFixed(2),Q=t.p-w>.15*v,x=e.leakSource==="system"&&e.leak>0,r="none";x&&!e.clamped?r="continuous":n&&e.leak>0?e.leak===3||e.sideHoleOut||e.suction?r="continuous":e.leak===2?r="every breath":r=e.ppv?"every breath":"with breaths":n&&e.sideHoleOut&&(r="continuous");let X=r==="continuous"||r!=="none"&&Q,T=e.suction?e.source>.7?"vigorous":e.source>.05?"gentle":"still":"still",Z=n?u>0?.3:1:0,Y=e.fluid==="none"?0:Math.round(e.rateMlH*Z),P=Math.round(e.initialMl+(e.fluid==="none"?0:e.rateMlH*e.hours)),S=!n&&e.leak>0&&e.leakSource==="patient",A=e.fluid==="blood"&&(e.initialMl>=1500||e.rateMlH>=200&&e.hours>=2),o=[];return n||o.push(e.clamped?"Clamped: no swing, no bubbling, no drainage.":e.kink?"Kinked tubing: the column is still and drainage has stopped.":"Clot in the tube: the column is still and drainage has stopped."),S&&o.push(e.ppv?"The lung is still leaking under positive pressure \u2014 with the drain occluded, tension will re-accumulate.":"An occluded drain on a leaking lung lets the pneumothorax re-accumulate."),n&&f>=.8?o.push(`Tidaling ${f} cm: the tube is patent and in the pleural space (${e.ppv?"falls with each ventilator breath":"rises with each breath in"}).`):n&&e.suction?o.push("On suction the swing is damped \u2014 turn suction off briefly to judge tidaling."):n&&e.expanded>.9&&u===0?o.push("Tidaling has almost stopped with a patent system: the lung has re-expanded against the tube."):n&&u===0&&o.push("Little swing: check the tubing for a partial obstruction and the patient for re-expansion."),u>0&&o.push(`Fluid in a dependent loop (~${Math.round(u)} cmH\u2082O) is opposing drainage.`),r!=="none"&&o.push(x?"Continuous bubbling from a SYSTEM leak \u2014 it continues when the tube is clamped briefly at the chest.":e.sideHoleOut?"Continuous bubbling with a side hole outside the chest wall \u2014 air is being drawn in at the insertion site.":r==="continuous"?"Continuous bubbling: a large air leak from the lung (bronchopleural fistula if it persists).":"Bubbling with breaths: an air leak from the lung \u2014 expected early after a pneumothorax; grade and trend it."),e.unitHigh&&o.push("The unit is above the chest: drained fluid can siphon back into the pleura."),e.sideHoleOut&&o.push("Subcutaneous emphysema around the site \u2014 a side hole has come out of the chest."),T==="vigorous"&&o.push("Vigorous bubbling in the suction-control chamber adds noise and evaporation, not suction \u2014 the water depth sets the pressure. Turn the wall source down to gentle bubbling."),A&&o.push(e.initialMl>=1500?`${e.initialMl} mL of blood on insertion: massive haemothorax \u2014 call surgery.`:`${e.rateMlH} mL/h of blood for ${e.hours} h: ongoing haemorrhage \u2014 call surgery.`),{patent:n,swing:f,level:$,bubblingNow:X,bubbling:r,suctionChamber:T,rate:Y,total:P,siphonBack:e.unitHigh&&P>0,subcutEmphysema:e.sideHoleOut,tensionRisk:S,surgical:A,findings:o}}function me(e,t){return e.leak===0&&!e.sideHoleOut?{bubblingStops:!0,meaning:"No bubbling to test."}:e.leakSource==="patient"||e.sideHoleOut?t==="chest"?{bubblingStops:!0,meaning:"Stops when clamped at the chest: the air is coming from the patient (lung leak, or the site if a side hole is out). Release the clamp at once."}:{bubblingStops:!0,meaning:"Stops: the leak is on the patient side of the clamp."}:t==="chest"?{bubblingStops:!1,meaning:"Still bubbling with the tube clamped at the chest: the leak is in the tubing or unit. Move the clamp down the tubing to find it; check every connection."}:{bubblingStops:!0,meaning:"Stops only when clamped at the unit end: the leak is in the tubing between the two clamp sites."}}var ee=e=>e.map(([t,s])=>({id:t,label:s})),l=ee([["observe","Expected \u2014 document and keep observing"],["unkink","Find and relieve the obstruction (kink / clot / clamp)"],["loop","Straighten the tubing and drain the loop into the chamber"],["leakCheck","Clamp briefly at the chest to locate the leak, then check connections"],["surgeon","Escalate: surgical review for haemorrhage"],["lower","Lower the unit below the chest"],["source","Turn the suction source down to gentle bubbling"],["site","Check the site: side hole out \u2014 secure, dress, arrange replacement"]]),be=[{id:"ok-ppv",title:"Swinging on the ventilator",story:"Day 1 after a drain for pneumothorax, ventilated, water seal only. The column falls with each ventilator breath; no bubbling.",cfg:{leak:0,expanded:.5},question:"What does this tell you?",options:l,answer:"observe",explain:"Tidaling means the tube is patent and in the pleural space. On positive pressure the pleural pressure rises in inspiration, so the column falls \u2014 the reverse of spontaneous breathing."},{id:"leak-ppv",title:"Bubbles with every breath",story:"Ventilated, 6 h after a drain for traumatic pneumothorax. Bubbles pass through the water seal with each ventilator breath; SpO\u2082 stable.",cfg:{leak:2,expanded:.6},question:"Best response?",options:l,answer:"observe",explain:"A patient air leak with each positive-pressure breath is expected early. Grade and trend it; never clamp a bubbling drain \u2014 the air has nowhere else to go."},{id:"kink",title:"Nothing moves",story:"Ventilated patient with a known air leak. The water seal is suddenly still, no bubbling, and peak pressures and heart rate are climbing.",cfg:{leak:2,kink:!0,expanded:.6},question:"Most likely problem and action?",options:l,answer:"unkink",explain:"Loss of swing AND of a known leak with deteriorating pressures means the drain is occluded \u2014 here a kink under the patient. Tension is re-accumulating. Relieve it now."},{id:"expanded",title:"Still water, well patient",story:"Day 3, spontaneous breathing, no bubbling for 24 h, chest X-ray shows the lung fully up. The column barely moves; tubing checked and patent.",cfg:{leak:0,expanded:1,ppv:!1,fluid:"serous",rateMlH:5},question:"Interpretation?",options:l,answer:"observe",explain:"With a patent, well-positioned system, tidaling fades as the lung re-expands against the tube. Absent tidaling is only reassuring when the patient and the tubing say so."},{id:"loop",title:"Fluid in the tubing",story:"Haemothorax drain. Drainage has slowed; a loop of tubing hangs off the bed below the unit inlet and is full of blood.",cfg:{fluid:"blood",rateMlH:60,loopMl:90,expanded:.5},question:"What do you do?",options:l,answer:"loop",explain:"A fluid-filled dependent loop is a column of fluid the pleura has to push against. Straighten the tubing, let the loop drain into the chamber, keep the tubing coiled flat on the bed."},{id:"system",title:"Continuous bubbling, new",story:"Spontaneously breathing patient whose leak had stopped. Now there is continuous bubbling in the water seal; the patient is comfortable, no subcutaneous emphysema.",cfg:{leak:1,leakSource:"system",ppv:!1,expanded:.95},question:"Next step?",options:l,answer:"leakCheck",explain:"A NEW continuous leak in a well patient is often the system. A brief clamp at the chest: if it keeps bubbling, the leak is between the clamp and the unit \u2014 check every connection."},{id:"site",title:"Crackling skin",story:"After a transfer the tube looks longer at the skin; there is new crackling under the skin around the site and continuous bubbling.",cfg:{leak:1,sideHoleOut:!0,ppv:!1},question:"Most likely problem?",options:l,answer:"site",explain:"A side hole outside the pleura draws air in at the site and pushes it into the tissues. Do not push the tube back in; secure it, occlusive dressing, and arrange replacement."},{id:"massive",title:"Blood on insertion",story:"Stab wound, drain inserted: 1600 mL of blood into the collection chamber immediately. HR 128, BP 86/50.",cfg:{fluid:"blood",initialMl:1600,rateMlH:150,hours:0,expanded:.5,ppv:!1},question:"What now?",options:l,answer:"surgeon",explain:"About 1500 mL on insertion (or around 200 mL/h for several hours) is haemorrhage the drain cannot fix. Resuscitate with blood and call surgery."},{id:"high",title:"On the stretcher",story:"During a transfer the unit has been placed on the patient\u2019s legs, level with the chest; fluid is running back up the tubing.",cfg:{fluid:"serous",initialMl:400,unitHigh:!0,ppv:!1},question:"Correct action?",options:l,answer:"lower",explain:"Keep the unit upright and below the chest at all times; above it, drained fluid siphons back into the pleura. Do not clamp for the move."},{id:"vigorous",title:"Roaring suction chamber",story:"Wet-suction unit at \u221220 cmH\u2082O. The suction-control chamber is bubbling violently and the water level keeps dropping.",cfg:{suction:!0,source:.95,leak:0},question:"What is the fix?",options:l,answer:"source",explain:"In a wet system the water depth sets the suction; more wall vacuum only makes it bubble harder and evaporate. Turn the source down until the bubbling is gentle, and top up to the ordered level."}],ge=e=>({...p,...e.cfg});var m=E(e=>({cfg:{...p},caseId:null,answer:null,test:null,set:t=>e(t)}));function c(e){let t={...m.getState().cfg,...e};m.getState().set({cfg:t,test:null}),a.setDrainBlocked(t.kink||t.clot||t.clamped)}var te={id:"wf-chest-tube",module:"vent",level:"advanced",title:"Tension pneumothorax: decompress, then drain",blurb:"Recognise tension on the ventilator, decompress immediately, then place a chest drain safely \u2014 and watch the lung, pressures and blood pressure respond.",context:"Ventilated trauma patient. Sudden high-pressure alarm: peak AND plateau pressures up, SpO\u2082 falling, BP 70/40, no breath sounds on the right, trachea deviating left.",setup:()=>{a.load("ptx")},steps:[{id:"recognise",label:"Call it: tension pneumothorax (clinical diagnosis)",why:"High peak and plateau pressures with hypotension, hypoxaemia and one silent side on a ventilated patient is tension until proven otherwise. It is treated before any imaging."},{id:"fio2",label:"FiO\u2082 1.0",why:"Buys oxygen reserve while you decompress."},{id:"needle",label:"Needle / finger decompression on the affected side",why:"Releases pleural pressure at once \u2014 venous return and blood pressure recover. Sites: 4th\u20135th intercostal space just anterior to the mid-axillary line, or 2nd space mid-clavicular; in a ventilated patient a finger thoracostomy at the lateral site is common.",critical:!0},{id:"site",label:"Choose the site: triangle of safety, 4th\u20135th space",why:"Bounded by the lateral edge of pectoralis major, the anterior edge of latissimus dorsi and a line at the level of the nipple. Lower sites risk diaphragm, liver and spleen."},{id:"prep",label:"Position (arm up), aseptic prep, local anaesthetic",why:"Arm abducted opens the space; asepsis prevents empyema; infiltrate down to the pleura and the periosteum."},{id:"dissect",label:"Incise, then blunt-dissect over the TOP of the rib into the pleura",why:"The intercostal artery, vein and nerve run in the groove under each rib. Going over the upper edge of the rib below avoids them.",critical:!0},{id:"sweep",label:"Finger sweep inside the pleura",why:"Confirms you are in the pleural space and there are no adhesions or organs in the way."},{id:"tube",label:"Guide the tube in (no sharp trocar), all side holes inside",why:"Directed apically for air. A side hole outside the chest wall leaks air into the tissues.",critical:!0},{id:"seal",label:"Connect to an underwater seal / drainage system, secure",why:"A one-way valve: air leaves, none returns. Secure and dress so it cannot be pulled out."},{id:"confirm",label:"Confirm: swing, bubbling, pressures & SpO\u2082 recover; chest X-ray",why:"Fluid swing with breathing and bubbling mean it is in the pleura; the X-ray checks position and re-expansion."}],anyOrder:[["site","prep"]],distractors:[{id:"xray",label:"Get a chest X-ray before decompressing",why:"Tension kills in minutes. Waiting for imaging is the classic avoidable death.",critical:!0},{id:"peep",label:"Increase PEEP to fix the oxygenation",why:"More positive pressure pushes more air through the leak and raises intrathoracic pressure further \u2014 pressures climb, blood pressure falls.",critical:!0},{id:"underRib",label:"Dissect along the lower edge of the rib above",why:"That is where the intercostal vessels and nerve run: bleeding and neuralgia.",critical:!0},{id:"trocar",label:"Push the tube in on a sharp trocar",why:"Sharp trocars cause lung, heart, liver and spleen injuries. Use blunt dissection and a finger.",critical:!0},{id:"low",label:"Insert at the 7th\u20138th space for easier access",why:"Below the safe triangle the diaphragm rises in expiration: abdominal organ injury.",critical:!0},{id:"clamp",label:"Clamp the drain for the CT transfer",why:"With an ongoing air leak on positive pressure, a clamped drain lets the tension re-accumulate."}],effects:{fio2:()=>a.set({fio2:1}),needle:()=>a.intervene("decompress"),tube:()=>a.intervene("chestTube"),peep:()=>a.set({peep:(a.m.s.peep??5)+6})},debrief:"Tension is a clinical diagnosis treated with immediate decompression; the drain is the definitive fix. The same ventilator numbers that raised the alarm \u2014 peak AND plateau pressure, SpO\u2082, blood pressure \u2014 confirm the result."},ae={id:"wf-dopes",module:"vent",level:"core",title:"Ventilated patient desaturating: DOPES",blurb:"Displacement, Obstruction, Pneumothorax, Equipment, Stacking \u2014 work through them in a safe order, and let the inspiratory hold tell resistance from compliance.",context:"Day 5 of ventilation. High-pressure alarm, SpO\u2082 88 % and falling, patient coughing. The tube is taped at 22 cm at the teeth.",setup:()=>{a.load("ett")},steps:[{id:"o2",label:"FiO\u2082 1.0; if unsure, disconnect and hand-ventilate with a bag",why:"Bagging takes the ventilator (Equipment) and breath stacking out of the equation at once, and lets you feel the resistance."},{id:"displacement",label:"Displacement: tube depth at the teeth, capnography waveform, chest rise",why:"Lost EtCO\u2082 waveform = the tube is out until proven otherwise. Here it is still there at 22 cm."},{id:"hold",label:"Inspiratory hold: compare peak and plateau",why:"Peak high with a NORMAL plateau means the pressure is being lost across resistance (tube or airways), not a stiff lung or chest."},{id:"suction",label:"Obstruction: pass a suction catheter",why:"It meets resistance and thick secretions come back \u2014 the tube was partly blocked.",critical:!0},{id:"ptx",label:"Pneumothorax: breath sounds and chest movement equal? (ultrasound lung sliding)",why:"Excluded here \u2014 but a ventilated patient with high pressures and hypotension has tension until proven otherwise."},{id:"reassess",label:"Reconnect and reassess: peak pressure, SpO\u2082, tidal volume",why:"The peak\u2013plateau gap should close once the tube is clear."}],anyOrder:[["displacement","hold"]],distractors:[{id:"alarm",label:"Raise the high-pressure alarm limit",why:"The alarm is telling you the tube is blocking. Silencing it removes the warning, not the problem.",critical:!0},{id:"sedate",label:"Give more sedation for \u201Cfighting the ventilator\u201D",why:"Treats the patient\u2019s response to a blocked tube, not the tube. Check the machine and the airway first."},{id:"paralyse",label:"Paralyse to bring the pressures down",why:"Masks the cause; with a blocked tube the peak pressure stays high anyway.",critical:!0},{id:"peep",label:"Raise PEEP for the desaturation",why:"A blocked tube is a resistance problem; more PEEP adds pressure without opening the tube."}],effects:{o2:()=>a.set({fio2:1}),hold:()=>a.hold("i"),suction:()=>a.intervene("suction"),paralyse:()=>a.intervene("paralyse"),peep:()=>a.set({peep:(a.m.s.peep??5)+5})},debrief:"Oxygen first, then a fixed order \u2014 Displacement, Obstruction, Pneumothorax, Equipment, Stacking. The inspiratory hold splits resistance (high peak, normal plateau) from compliance (both high)."},ie={id:"wf-drain-check",module:"vent",level:"core",title:"Chest drain assessment",blurb:"Hourly check of a three-chamber drain: patient, site, tubing, unit, suction, tidaling, air leak and drainage \u2014 with a live water seal driven by the patient\u2019s pleural pressure.",context:"Ventilated patient, 4 h after a right chest drain for tension pneumothorax, water seal with an air leak. Peak pressures have crept up over the last few minutes. You start your drain check.",setup:()=>{a.load("ptx"),a.intervene("decompress"),a.intervene("chestTube");for(let e=0;e<12*20;e++)a.tick(.05);m.getState().set({caseId:null,answer:null,test:null,cfg:{...p,leak:2,expanded:.7}}),c({kink:!0})},steps:[{id:"patient",label:"Patient first: SpO\u2082, ventilator pressures, breath sounds, chest movement, pain",why:"The drain exists for the patient. Rising peak and plateau pressures with a falling SpO\u2082 in someone with a drain means the drain may not be working."},{id:"site",label:"Insertion site: dressing dry and occlusive, depth mark unchanged, no subcutaneous emphysema",why:"A tube that has slipped out puts side holes outside the pleura \u2014 air is drawn in and tracks under the skin."},{id:"tubing",label:"Trace the tubing from chest to unit: no kinks, no dependent loops, connections secure, not under the patient",why:"Here the patient is lying on it: a kink. Freed, the swing and the leak bubbles return and the pressures come down.",critical:!0},{id:"unit",label:"Unit upright and below the chest",why:"Above the chest, fluid siphons back into the pleura; tipped over, the water seal is lost.",critical:!0},{id:"suction",label:"Suction as ordered (or water seal only): gentle bubbling in the suction chamber",why:"In a wet system the water depth sets the suction; vigorous bubbling adds nothing but noise and evaporation."},{id:"swing",label:"Water seal at its level; watch for tidaling (suction briefly off if needed)",why:"Tidaling means the tube is patent and in the pleural space. On the ventilator the column falls with each breath."},{id:"leak",label:"Air leak: pattern and grade \u2014 with breaths, every breath, continuous",why:"A leak that is getting smaller means the lung is sealing; a new continuous leak means check the system."},{id:"output",label:"Drainage: volume, colour and rate; mark the level with the time",why:"Trends matter: a sudden fall in bloody output with worsening vital signs is a blocked tube, not a stopped bleed."}],anyOrder:[["suction","swing","leak","output"]],distractors:[{id:"clamp",label:"Clamp the drain while you sort it out",why:"The lung is still leaking under positive pressure. A clamped drain turns an air leak into a tension pneumothorax.",critical:!0},{id:"bed",label:"Lift the unit onto the bed beside the patient",why:"Level with or above the chest, fluid runs back into the pleura.",critical:!0},{id:"topup",label:"Add water to the water seal to stop the bubbling",why:"The bubbles are air leaving the lung \u2014 the leak is in the patient, not the seal. A deeper seal only makes the air work harder to get out."},{id:"strip",label:"Strip (milk) the whole tubing hard every hour",why:"Stripping generates very high negative pressures at the tube tip. Only gentle milking of a visible clot, if local policy allows."},{id:"push",label:"Push the tube further in to improve it",why:"The external part is not sterile; a migrated tube is secured and replaced, never advanced.",critical:!0}],effects:{tubing:()=>c({kink:!1}),clamp:()=>c({clamped:!0}),bed:()=>c({unitHigh:!0})},debrief:"Check the drain from the patient outward: patient, site, tubing, unit, then the chambers. Swing and bubbling are the drain talking \u2014 their sudden disappearance on a leaking lung is an emergency, and the ventilator shows it before anyone looks at the unit."},se={id:"wf-low-pressure",module:"vent",level:"core",title:"Low-pressure alarm: disconnection and cuff leak",blurb:"Peak pressure and exhaled volume have collapsed: find the open circuit, then the leak around the cuff \u2014 and watch the lung lose its PEEP while you look.",context:"Ventilated patient just moved from the stretcher to the aircraft litter. Low-pressure and low exhaled-volume alarms, peak pressure barely above zero, the capnography waveform has gone, SpO\u2082 starting to fall.",setup:()=>{a.load("ards"),a.set({peep:12,vt:.42});for(let e=0;e<10*20;e++)a.tick(.05);a.circuit("both")},steps:[{id:"look",label:"Look at the patient: chest rise, SpO\u2082, capnography waveform; listen for gas escaping",why:"No chest rise and a lost EtCO\u2082 trace with a low peak pressure means gas is not reaching the lungs \u2014 an open circuit until proven otherwise."},{id:"trace",label:"Trace the circuit from the tube to the ventilator: tube connector, HME/filter, wye, inline suction, water traps",why:"Here the HME has come off the tube connector in the move. Reconnected: pressures and volumes return at once.",critical:!0},{id:"bag",label:"If the fault is not found at once: bag with 100 % oxygen and a PEEP valve while you look",why:"The patient is not ventilated while you search. A bag with a PEEP valve keeps oxygenation up without losing the recruited lung."},{id:"volumes",label:"Compare inspired and exhaled tidal volume",why:"Still a gap after reconnecting: gas is going in but not all of it is coming back \u2014 a leak between the ventilator and the alveoli."},{id:"cuff",label:"Check the cuff: audible leak at the mouth, cuff pressure 20\u201330 cmH\u2082O, tube depth at the teeth",why:"An under-filled cuff (or a tube pulled back so the cuff sits between the cords) leaks every breath. Re-inflate to the target pressure and confirm depth.",critical:!0},{id:"recruit",label:"Reassess: exhaled volume = set, peak pressure back, EtCO\u2082 waveform, SpO\u2082; consider a recruitment step after the PEEP was lost",why:"An ARDS lung derecruits within seconds of losing PEEP. Oxygenation may lag behind the restored pressures."}],anyOrder:[["trace","bag"]],distractors:[{id:"silence",label:"Silence the alarm and carry on with the transfer",why:"A low-pressure alarm on a paralysed patient is a disconnection until proven otherwise. The alarm is the only warning before hypoxia.",critical:!0},{id:"limit",label:"Lower the low-pressure alarm limit so it stops sounding",why:"The limit exists to catch exactly this. Set it a few cmH\u2082O below the patient\u2019s usual peak, never to zero.",critical:!0},{id:"vt",label:"Increase the set tidal volume to make up the lost volume",why:"With the circuit open the extra volume goes into the room; once reconnected it becomes a high tidal volume in an ARDS lung."},{id:"sedate",label:"Give more sedation",why:"The patient is not the problem \u2014 the circuit is."}],effects:{trace:()=>a.circuit(a.circuitFault==="both"?"cuffLeak":a.circuitFault==="disconnect"?"none":a.circuitFault),cuff:()=>a.circuit(a.circuitFault==="both"?"disconnect":a.circuitFault==="cuffLeak"?"none":a.circuitFault),bag:()=>a.set({fio2:1}),vt:()=>a.set({vt:.6})},debrief:"A low-pressure alarm is gas escaping: look at the patient, trace the circuit hand over hand, bag if you cannot fix it at once, then compare inspired and exhaled volumes to find a leak nearer the patient. The ventilator shows each fault in its own numbers \u2014 peak pressure near zero with nothing coming back is an open circuit; a steady gap between inspired and exhaled volume is a leak."},W=[te,ie,ae,se];var M=(e,t)=>e*1e3/t,q=(e,t,s)=>e*t*60/s,Ae=(e,t,s)=>e*s/(t*60);var y=(e,t)=>e/t,F=(e,t,s)=>e*t/s;var d=80,g=M(4,250),B=q(.1,d,g),b=F(1e4,1,100),oe={id:"wf-blood",module:"lines",level:"core",title:"Starting a blood transfusion safely",blurb:"From indication to the first 15 minutes: identity checks, the right line and the right observations \u2014 on a bleeding patient whose numbers respond.",context:"Trauma patient, still bleeding: HR 118, BP falling, CVP low, arterial line in. Two units of red cells are on their way.",setup:()=>{i.load("hypovol")},steps:[{id:"indication",label:"Confirm the indication (haemorrhagic shock)",why:"Tachycardia, low filling pressure and ongoing loss \u2014 the haemoglobin can still look normal early because nothing has diluted it yet."},{id:"sample",label:"Group & crossmatch sample, labelled at the bedside",why:"Samples labelled away from the patient are a classic source of wrong-blood-in-tube."},{id:"product",label:"Choose the product (crossmatched, or emergency group O if it cannot wait); call the major-haemorrhage protocol if bleeding continues",why:"Ongoing major bleeding needs plasma and platelets as well as red cells, not red cells alone."},{id:"check",label:"Two-person bedside check: ID band \u2194 unit label \u2194 prescription",why:"Almost all ABO-incompatible transfusions come from wrong-patient errors at the bedside, not from the laboratory.",critical:!0},{id:"obs",label:"Baseline temperature, HR, BP, RR, SpO\u2082",why:"A reaction is recognised as a CHANGE from baseline."},{id:"set",label:"Blood giving set with filter; warmer for rapid transfusion; saline only on that line",why:"The filter catches clots; cold blood worsens coagulopathy; dextrose and many drugs are incompatible."},{id:"start",label:"Start, and stay with the patient for the first 15 minutes",why:"Severe reactions (ABO incompatibility, anaphylaxis) usually declare themselves early."},{id:"reassess",label:"Reassess after each unit: HR, BP, CVP, Hb, bleeding",why:"Transfuse to physiology and bleeding control, not to a single number."},{id:"source",label:"Stop the bleeding (surgery / interventional radiology)",why:"Blood buys time; only source control ends haemorrhagic shock."}],anyOrder:[["sample","product"],["obs","set"]],distractors:[{id:"dextrose",label:"Run it through the 5 % dextrose line that is already up",why:"Dextrose causes red-cell clumping and haemolysis. Only 0.9 % saline may share the line.",critical:!0},{id:"skipId",label:"Skip the bedside check \u2014 the lab has crossmatched it",why:"The crossmatch is only as good as the identity of the patient receiving it.",critical:!0},{id:"coinfuse",label:"Co-infuse antibiotics through the blood line",why:"Incompatibility, and if a reaction occurs you cannot tell which caused it."},{id:"crystalloid",label:"Keep giving crystalloid until the Hb drops",why:"Large crystalloid volumes dilute clotting factors and haemoglobin and cool the patient."},{id:"warmRoom",label:"Leave the unit on the bed for an hour to warm up",why:"Bacterial growth: units must start promptly after leaving controlled storage and finish within the local time limit. Use a blood warmer."}],effects:{start:()=>i.transfuse(),reassess:()=>i.transfuse(),crystalloid:()=>{i.fluid(),i.fluid()}},debrief:"Identity checks at the bedside prevent the catastrophic errors; the first 15 minutes catch the early reactions; and every unit is followed by a reassessment \u2014 while someone stops the bleeding."},ne={id:"wf-nore",module:"lines",level:"core",title:"Starting a norepinephrine infusion",blurb:`Concentration, rate and the double-check: ${Math.round(g)} \xB5g/mL, 0.1 \xB5g/kg/min for ${d} kg = ${Math.round(B)} mL/h \u2014 then watch the arterial line respond.`,context:`Septic shock after 30 mL/kg of fluid: MAP in the 50s, warm peripheries, wide pulse pressure. Weight ${d} kg. Norepinephrine 0.1 \xB5g/kg/min prescribed.`,setup:()=>{i.load("sepsis")},steps:[{id:"target",label:"Set the target: MAP \u2265 65 mmHg",why:"A common starting target; higher targets add arrhythmias and ischaemia without clear benefit for most patients."},{id:"order",label:`Confirm drug, weight (${d} kg) and dose units (\xB5g/kg/min)`,why:"\xB5g/min and \xB5g/kg/min differ by a factor of the body weight \u2014 an 80-fold error."},{id:"conc",label:`Standard concentration: 4 mg in 250 mL = ${Math.round(g)} \xB5g/mL; label it`,why:"Standard concentrations make pump libraries and double-checks work."},{id:"calc",label:`Rate = 0.1 \xD7 ${d} \xD7 60 \xF7 ${Math.round(g)} = ${Math.round(B)} mL/h`,why:"Dose (\xB5g/kg/min) \xD7 weight \xD7 60 \xF7 concentration (\xB5g/mL) = mL/h."},{id:"double",label:"Independent double-check: drug, concentration, rate, pump programme",why:"Done independently \u2014 not by reading the first person\u2019s numbers back.",critical:!0},{id:"line",label:"Dedicated lumen (central preferred; peripheral short-term in a large proximal vein, site checked)",why:"Nothing else is flushed through it, and extravasation is spotted early."},{id:"start",label:"Start and titrate every few minutes to the target",why:"Watch the arterial line: SVR rises, diastolic and mean pressures climb; the heart rate barely changes in a hypotensive patient."},{id:"monitor",label:"Beyond MAP: lactate, urine output, mental state, skin, the infusion site",why:"Pressure is a means; perfusion is the goal."}],anyOrder:[["conc","order"]],distractors:[{id:"units",label:"Programme 0.1 \xB5g/min",why:`For ${d} kg that is 1/${d} of the prescribed dose \u2014 the MAP will not move and the dose will be "escalated" blindly.`,critical:!0},{id:"sameLumen",label:"Run it into the lumen used for fluid boluses",why:"Every bolus flushes the dead space \u2014 a surge of pressor \u2014 and pauses leave the patient without it.",critical:!0},{id:"skipCheck",label:"Skip the double-check, it is urgent",why:"Urgency is when calculation errors happen.",critical:!0},{id:"map90",label:"Aim for MAP 90 to be safe",why:"More vasoconstriction, more afterload, more arrhythmia \u2014 without better outcomes for most patients."}],effects:{start:()=>i.setNore(.1),map90:()=>i.setNore(.3)},debrief:"Right drug, right concentration, right units, checked independently, on its own line \u2014 and titrated to perfusion, not just a number."},re={id:"wf-push",module:"lines",level:"advanced",title:"Push-dose phenylephrine for transient hypotension",blurb:`Make ${b} \xB5g/mL from a 10 mg/mL vial, push ${y(100,b)} mL, and watch pressure rise and the heart rate fall \u2014 then fade.`,context:"Moments after induction for intubation the MAP drops to the 50s. An infusion is being prepared; you need a short bridge.",setup:()=>{i.load("sepsis")},steps:[{id:"recognise",label:"Transient hypotension: bridge it while you treat the cause",why:"Push-dose pressors are a bridge, not a treatment for ongoing shock."},{id:"dilute",label:`Dilute: 10 mg (1 mL of 10 mg/mL) into 100 mL saline \u2192 ${b} \xB5g/mL; draw 10 mL`,why:"The vial is 100 times too concentrated to push.",critical:!0},{id:"label",label:"Label the syringe: drug and \xB5g/mL",why:"Unlabelled syringes of vasopressor are a recognised cause of catastrophic errors.",critical:!0},{id:"push",label:`Give 100 \xB5g (${y(100,b)} mL) and flush`,why:"Onset within about a minute; effect lasts roughly 10\u201320 minutes at the bedside (compressed on screen)."},{id:"watch",label:"Watch MAP and heart rate over 1\u20132 minutes",why:"Pure \u03B11: SVR up, pressure up \u2014 and the baroreflex slows the heart."},{id:"infusion",label:"Needing repeated doses? Start an infusion",why:"Repeated pushes give swinging pressures."},{id:"cause",label:"Treat the cause (volume, sedative dose, sepsis source)",why:"The pressor hides the problem; it does not fix it."}],distractors:[{id:"undiluted",label:"Push the vial undiluted (10 mg/mL)",why:"A 100-fold overdose: severe hypertension, reflex bradycardia, stroke, pulmonary oedema.",critical:!0},{id:"epi1mg",label:"Draw 10 \xB5g from the 1 mg/mL epinephrine vial",why:"Measuring 0.01 mL is impossible \u2014 dilute to 10 \xB5g/mL first.",critical:!0},{id:"brady",label:"Choose phenylephrine for a hypotensive patient who is already bradycardic",why:"Reflex slowing makes it worse; epinephrine (\u03B1 + \u03B2) is the better push-dose choice."}],effects:{push:()=>i.pushDose("phenylephrine",100),infusion:()=>i.setNore(.08)},debrief:"Dilute, label, small dose, watch \u2014 and use the time to fix the cause or start an infusion."},le={id:"wf-artline",module:"lines",level:"core",title:"Arterial line: level, zero, flush test, fix",blurb:"An over-reading arterial line: find out whether the number or the patient is wrong \u2014 levelling, zeroing, the square-wave test and the fix, on the live transducer.",context:"New radial arterial line. The monitor shows a spiky systolic of about 150 while the patient looks well. The transducer has slipped down the pole; nobody has checked the damping.",setup:()=>{i.load("normal"),i.setup.transH=i.axis-10,i.setFault("art","smallBubble"),i.setStopcock("art","patient")},steps:[{id:"cuff",label:"Cross-check with a cuff pressure",why:"Cuff and arterial MEAN pressures should agree closely; systolic can legitimately differ. A large disagreement means check the system before treating."},{id:"level",label:"Level the transducer to the phlebostatic axis",why:"4th intercostal space, mid-chest. Every 10 cm below the axis adds about 7 mmHg to every reading."},{id:"air",label:"Stopcock off to the patient, open to air",why:"Zeroing sets atmospheric pressure as 0 \u2014 the transducer must see air, not the patient."},{id:"zero",label:"Zero on the monitor",why:"Removes electrical and hydrostatic offset in the transducer itself.",critical:!0},{id:"back",label:"Cap the port, stopcock back to the patient",why:"An open port reads atmospheric pressure (a flat zero) and can bleed or entrain air.",critical:!0},{id:"flushTest",label:"Square-wave (fast-flush) test",why:"Pull the flush: after the square wave, 1.5\u20132 oscillations before the trace returns is optimal. More = underdamped (over-reads systolic), fewer = overdamped (under-reads systolic)."},{id:"fix",label:"Underdamped: off to the patient, aspirate / flush the bubble to waste",why:"A small bubble drops the natural frequency and the trace rings. It must leave through the side port, never toward the patient."},{id:"retest",label:"Repeat the flush test, then trust the trace",why:"Now the systolic and diastolic are believable; the mean was the most robust number all along."}],anyOrder:[["cuff","level"]],distractors:[{id:"zeroPatient",label:"Zero with the stopcock still open to the patient",why:"The monitor subtracts the patient\u2019s own pressure as if it were zero: every reading drops by tens of mmHg and a normal patient suddenly looks shocked.",critical:!0},{id:"flushFwd",label:"Flush the bubble forward into the artery",why:"Air from a radial line can travel retrograde to the brain. Always flush air out of the side port to waste.",critical:!0},{id:"bed",label:"Level the transducer to the mattress",why:"The reference is the heart (phlebostatic axis), not the bed \u2014 raising the head of the bed moves the axis."},{id:"treat",label:"Start a vasodilator for the high systolic",why:"Treating an artefact. Check level, zero and damping first."}],effects:{cuff:()=>i.startNibp(),level:()=>i.levelToAxis(),air:()=>i.setStopcock("art","air"),zero:()=>i.zero("art"),back:()=>i.setStopcock("art","patient"),flushTest:()=>i.flush("art"),fix:()=>{i.act("art","aspirate")},retest:()=>i.flush("art"),zeroPatient:()=>{i.setStopcock("art","patient"),i.zero("art")},flushFwd:()=>{i.act("art","flushForward")},bed:()=>{i.setup.transH=i.setup.bedH,i.version++}},debrief:"Before treating an arterial number: is it levelled, zeroed and properly damped? The mean pressure survives damping errors best; levelling errors shift every number."},z=[oe,ne,re,le];var _=[{id:"alarm-ett",kind:"alarm",level:"Novice",title:"High-pressure alarm #1",scenario:"ett",brief:"The high-pressure alarm keeps sounding. Do an inspiratory hold and compare PIP with Pplat.",question:"Where is the extra pressure going?",options:["Resistance \u2014 the airway or tube (PIP \u2191, Pplat normal)","Compliance \u2014 the lung or chest (PIP \u2191 and Pplat \u2191)","Auto-PEEP","It is a sensor fault"],answer:0,explain:"PIP rose but Pplat did not: the gap (PIP \u2212 Pplat = R \xD7 flow) widened. The problem is between the ventilator and the alveoli.",action:{question:"What do you do first?",options:["Suction the ETT / check for kinks or biting","Increase PEEP","Needle decompression","Reduce FiO\u2082"],answer:0,explain:"Secretions in the tube raise resistance. Suction \u2014 and watch PIP fall back to baseline while Pplat stays the same."}},{id:"alarm-ptx",kind:"alarm",level:"Intermediate",title:"High-pressure alarm #2",scenario:"ptx",brief:"Sudden high-pressure alarm, SpO\u2082 falling, BP dropping. Use a hold and look at the lungs.",question:"Where is the extra pressure going?",options:["Resistance \u2014 the airway or tube","Compliance \u2014 the lung/pleura/chest (PIP \u2191 and Pplat \u2191 together)","Flow starvation","Leak"],answer:1,explain:"PIP and Pplat rose together with a normal gap: it now takes more pressure to fit the same volume into the chest. With hypotension that is a tension pneumothorax until proven otherwise.",action:{question:"Next step?",options:["Needle decompression / chest tube","Bronchodilator","Suction","Increase the tidal volume"],answer:0,explain:"Decompression lets the lung re-expand, Pplat falls and venous return \u2014 and blood pressure \u2014 recover."}},{id:"alarm-plug",kind:"alarm",level:"Intermediate",title:"Desaturation after turning",scenario:"plug",brief:"SpO\u2082 dropped after a turn. Breath sounds absent on the right. Look at the lungs and do a hold.",question:"What best explains the numbers?",options:["Whole Vt going into one lung \u2014 right main bronchus plugged","Bronchospasm","ETT in the oesophagus","Pulmonary embolus"],answer:0,explain:"One lung receives the whole tidal volume, so Pplat rises. The unventilated right lung is still perfused: a large shunt that FiO\u2082 barely touches.",action:{question:"Fix?",options:["Suction / bronchoscopy to clear the plug, then recruit","FiO\u2082 1.0 and wait","Lower PEEP","Increase RR"],answer:0,explain:"Clearing the plug restores ventilation to the right lung; watch both lungs move and the shunt fall."}},{id:"dys-autopeep",kind:"dyss",dyss:"autopeep",level:"Novice",title:"Waveform detective: asthma",scenario:"asthma",brief:"Paralysed asthmatic on VC. Look at the flow trace between breaths."},{id:"dys-fs",kind:"dyss",dyss:"flow-starvation",level:"Intermediate",title:"Waveform detective: air hunger",scenario:"normal",brief:"Agitated patient on volume control, breathing hard. Look at the shape of the pressure curve during inflation."},{id:"dys-dt",kind:"dyss",dyss:"double",level:"Intermediate",title:"Waveform detective: two for one",scenario:"normal",brief:"The set rate is 12 but the vent counts 24. Watch the breaths come in pairs."},{id:"dys-ie",kind:"dyss",dyss:"ineffective",level:"Advanced",title:"Waveform detective: COPD",scenario:"copd",brief:"The patient\u2019s chest is moving more often than the vent is breathing. Look at the expiratory flow."},{id:"dys-pc",kind:"dyss",dyss:"premature",level:"Advanced",title:"Waveform detective: pressure support #1",scenario:"normal",brief:'Patient on PSV looks uncomfortable. Toggle "Patient effort" only after you decide.'},{id:"dys-dc",kind:"dyss",dyss:"delayed",level:"Advanced",title:"Waveform detective: pressure support #2",scenario:"copd",brief:"COPD patient on PSV 14 is fighting the vent at the end of each breath."},{id:"dys-st",kind:"dyss",dyss:"stacking",level:"Expert",title:"Waveform detective: ARDS",scenario:"ards",brief:"ARDS patient with high drive on low-Vt VC. Look at the exhaled volumes."},{id:"goal-ards",kind:"goal",level:"Advanced",title:"Protect the ARDS lung",scenario:"ards",brief:'PBW 70 kg. Make this ventilation lung-protective AND keep the patient oxygenated. Use "+30 min" to see the gas.',goals:[{label:"Vt \u2264 6.5 mL/kg PBW",test:e=>e.vtPerKg<=6.6},{label:"Plateau \u2264 30 cmH\u2082O",test:e=>e.pplat<=30.5},{label:"Driving pressure \u2264 15",test:e=>e.dp<=15.5},{label:"SpO\u2082 \u2265 88 %",test:(e,t)=>t.spo2>=.875},{label:"pH \u2265 7.25",test:(e,t)=>t.pH>=7.245}]},{id:"goal-asthma",kind:"goal",level:"Advanced",title:"Let the asthmatic exhale",scenario:"asthma",settings:{rr:26,vt:.55,flow:45},brief:"Dynamic hyperinflation is dropping the blood pressure. Get the trapped gas out without letting the pH crash.",goals:[{label:"Auto-PEEP < 3 cmH\u2082O",test:e=>e.autoPeep<3},{label:"Plateau \u2264 30",test:e=>e.pplat<=30.5},{label:"MAP \u2265 65",test:(e,t)=>t.map>=64.5},{label:"pH \u2265 7.20 (permissive hypercapnia)",test:(e,t)=>t.pH>=7.195}]}];var j=[{id:"k-hd",level:"Intermediate",story:"Dialysis patient who missed two sessions. Weak, HR 48. ECG: wide QRS.",values:{k:7.3,hco3:17,cr:9},focus:"k",renal:.05,q:"First drug?",options:["IV calcium","Insulin + dextrose","K\u207A binder","Sodium bicarbonate"],answer:0,explain:"With ECG changes, stabilise the membrane first: calcium raises the threshold within minutes. Then shift (insulin, salbutamol), then remove (dialysis)."},{id:"na-acute",level:"Intermediate",story:"Marathon runner, drank litres of water; now confused, then seizes.",values:{na:117},focus:"na",q:"Next step?",options:["3 % saline bolus 100\u2013150 mL, repeat to stop symptoms","Fluid restriction only","Normal saline 2 L fast","Wait for a repeat sample"],answer:0,explain:"Acute, symptomatic hyponatraemia means brain oedema. A 4\u20136 mEq/L rise with hypertonic saline pulls water out of brain cells and stops seizures."},{id:"na-chronic",level:"Advanced",story:"Elderly woman on a thiazide for months, mildly unsteady, otherwise well.",values:{na:116},focus:"na",naChronic:!0,q:"What limits your treatment?",options:["Rise \u2264 8\u201310 mEq/L in 24 h","Correct to 135 today","Nothing \u2014 treat the number fast","Avoid checking sodium for 48 h"],answer:0,explain:"Her brain has adapted. Correcting faster than ~8\u201310 mEq/L per day risks osmotic demyelination. Stop the thiazide, correct slowly, check sodium often."},{id:"anaemia",level:"Novice",story:"Melaena, pale, HR 124. SpO\u2082 98 % on air.",values:{hb:6.2},focus:"hb",q:"What does the SpO\u2082 tell you?",options:["Only that the haemoglobin present is saturated \u2014 oxygen content is halved","Oxygen delivery is fine","He is not anaemic","He needs oxygen"],answer:0,explain:"SpO\u2082 measures saturation, not quantity. CaO\u2082 = 1.34 \xD7 Hb \xD7 SaO\u2082: with Hb 6 the content is roughly half. Transfuse and stop the bleeding."},{id:"lactate",level:"Intermediate",story:"Septic shock, MAP 58 on noradrenaline, mottled knees.",values:{lac:6.2},focus:"lac",q:"Best interpretation?",options:["Production outruns clearance: restore perfusion, control the source, re-measure","Give bicarbonate to fix it","It is only from salbutamol \u2014 ignore","Stop all fluids"],answer:0,explain:"Hypoperfusion, adrenergic glycolysis and a poorly perfused liver all contribute. The trend after resuscitation is what matters."},{id:"hypo",level:"Novice",story:"Insulin-treated diabetic found confused and sweaty.",values:{glu:36},focus:"glu",q:"First action?",options:["IV dextrose (or glucagon IM)","CT head","Insulin","Wait for the lab glucose"],answer:0,explain:"The brain runs on glucose. Treat immediately and recheck; look for the cause (sulfonylureas cause prolonged hypoglycaemia)."},{id:"inr",level:"Intermediate",story:"On warfarin, vomiting blood, BP 88/50.",values:{inr:6.5,hb:8},focus:"inr",q:"Reversal?",options:["IV vitamin K + prothrombin complex concentrate","Vitamin K orally and wait","Platelet transfusion","Protamine"],answer:0,explain:"PCC replaces factors II, VII, IX and X immediately; vitamin K lets the liver make its own over 6\u201324 h."},{id:"hit",level:"Advanced",story:"Day 7 of heparin after surgery. Platelets 210 \u2192 62. New leg DVT.",values:{plt:62},focus:"plt",q:"What now?",options:["Stop all heparin; start a non-heparin anticoagulant; test for HIT","Transfuse platelets","Increase the heparin","Stop anticoagulation entirely"],answer:0,explain:"HIT is prothrombotic: platelets fall because they are consumed in clots. Heparin must stop, but anticoagulation must continue with a non-heparin drug."},{id:"ca-mtp",level:"Intermediate",story:"10 units of blood in 2 hours for trauma. BP drifting down, oozing.",values:{ca:.82},focus:"ca",q:"Why is calcium low, and what do you do?",options:["Citrate in stored blood binds calcium \u2014 give IV calcium","Parathyroid failure \u2014 give vitamin D","Dilution \u2014 ignore","Alkalosis \u2014 give acid"],answer:0,explain:"Citrate anticoagulant chelates ionised calcium. Low iCa worsens contractility, vascular tone and clotting (calcium is factor IV)."},{id:"mg",level:"Intermediate",story:"Alcohol use disorder, QTc 540, runs of polymorphic VT.",values:{mg:1,k:3.1},focus:"mg",q:"Treatment?",options:["IV magnesium sulfate (and replace K\u207A)","Amiodarone","Wait for cardiology","Calcium chloride"],answer:0,explain:"Magnesium is first-line for torsades and is needed before potassium will stay up."},{id:"aki",level:"Novice",story:"Post-op day 1: creatinine 0.6 yesterday, 1.2 today. Urine output low.",values:{cr:1.2},focus:"cr",q:"Is this significant?",options:["Yes \u2014 creatinine doubled: GFR roughly halved (AKI)",'No \u2014 still "normal"',"Only if it reaches 3","Only if K\u207A is high"],answer:0,explain:"The relationship is inverse and steep at the low end. A doubling from any baseline is stage 2 AKI."},{id:"dka",level:"Intermediate",story:"Vomiting, deep breathing, glucose 480.",values:{glu:480,ket:6,hco3:9,k:5.4},focus:"ag",q:"Before starting insulin, which result must you check?",options:["Potassium","Troponin","Albumin","INR"],answer:0,explain:"Total-body K\u207A is depleted in DKA even when plasma K\u207A is high. Insulin drives K\u207A into cells; start it only once K\u207A \u2265 3.5 and replace K\u207A as it falls."},{id:"phos",level:"Advanced",story:"Malnourished patient, day 3 of tube feeds, failing to wean from the ventilator.",values:{phos:.9},focus:"phos",q:"What is the link?",options:["Refeeding hypophosphataemia: no ATP for the diaphragm","Too much sedation","Hypercalcaemia","The feeds contain too much salt"],answer:0,explain:"Insulin surges with feeding drive phosphate into cells. Without phosphate there is no ATP or 2,3-DPG: weak diaphragm, poor O\u2082 unloading. Replace and slow the feed."}];var G=e=>e.art.fault==="none"&&e.cvp.fault==="none"&&Math.abs(e.levelErr)<1.5&&["art","cvp"].every(t=>{let s=e.line(t);return s.stopcock==="patient"&&Math.abs(s.drift-s.zeroRef)<2}),Ne=G,K=[{id:"c-bubble",kind:"fix",level:"Novice",title:"The BP that nobody believes",setup:{scenario:"normal",art:"smallBubble",view:"bed"},brief:"The arterial line reads about 135/73 and the trace looks spiky. The cuff just read about 115/78. The patient looks well.",question:"What is the most likely problem?",options:["Underdamped line \u2014 resonance from a small bubble or long tubing","Overdamped line \u2014 a clot at the tip","The transducer is too low","True hypertension \u2014 the cuff is wrong"],answer:0,explain:"A systolic overshoot with a normal MAP and a ringing square-wave test is underdamping. Do a fast-flush test (more than 2 oscillations), find the bubble, aspirate and flush."},{id:"c-hob",kind:"fix",level:"Novice",title:"CVP 25 after the chest X-ray",setup:{scenario:"normal",hob:30,fromHob:0,view:"level"},brief:"The bed was sat up to 30\xB0 for a chest X-ray. Since then the CVP reads about 25 and the MAP has risen 20 mmHg. Nothing else has changed and the patient looks the same.",question:"Why did both pressures jump?",options:["The phlebostatic axis rose but the transducer did not \u2014 it now sits below the axis","Fluid overload from the X-ray contrast","The transducer drifted \u2014 it needs zeroing","Tension pneumothorax"],answer:0,explain:"Both lines rose by the same amount at the same moment: a reference-level error. Sitting the patient up raised the axis about 27 cm, so every reading is \u2248 20 mmHg too high. Re-level the transducer to the axis."},{id:"c-openair",kind:"fix",level:"Novice",title:"Flat line after the blood gas",setup:{scenario:"normal",art:"openAir",view:"bed"},brief:"Two minutes after an arterial blood gas was drawn, the monitor alarms: ART reads 0 with a flat trace. The patient is talking to you.",question:"What happened?",options:["The sampling stopcock was left open to air","Cardiac arrest","Massive clot in the radial artery","The pressure bag burst"],answer:0,explain:"A flat line at zero in a talking patient is a system problem. The sampling port was left open to air with the stopcock off to the patient, so the transducer reads atmosphere. Cap it, turn the stopcock back to the patient, and check for blood loss. (Had it been left open toward the patient, blood would run out \u2014 or, on a central line, air would be drawn in.)"},{id:"c-clot",kind:"fix",level:"Intermediate",title:"Blunted and getting worse",setup:{scenario:"normal",art:"clot",view:"wrist"},brief:"The arterial trace has lost its dicrotic notch and looks rounded. Systolic has drifted down to about 110. Drawing blood back from the sampling port is sluggish.",question:"What is the problem?",options:["Overdamped: a clot at the catheter tip","Underdamped: long tubing","Hypovolaemia","Aortic stenosis"],answer:0,explain:"Rounded trace, lost notch, low systolic, high diastolic, MAP unchanged, and a square-wave test with no bounce: overdamped. Sluggish blood return points to a clot. Aspirate it \u2014 never flush a clot forward into the radial artery."},{id:"c-zero",kind:"fix",level:"Intermediate",title:"Hypotension that isn\u2019t",setup:{scenario:"normal",zeroWrong:"art",view:"bed"},brief:"After the transducer was changed, the arterial line reads 26/\u221221 with a perfect-looking waveform. The patient is pink and talking; the cuff reads about 115/78.",question:"What went wrong?",options:["It was zeroed while open to the patient","The transducer is 60 cm too high","Severe vasodilatory shock","The line is overdamped"],answer:0,explain:"The shape is normal but the whole waveform is shifted down by about the patient\u2019s own mean pressure. Zeroing with the stopcock open to the patient made the monitor treat the MAP as \u201Czero\u201D. Turn the stopcock off to the patient, open to air, zero, and turn it back."},{id:"c-bag",kind:"fix",level:"Intermediate",title:"Blood in the tubing",setup:{scenario:"normal",art:"lowBag",view:"bed"},brief:"Blood has crept up the arterial tubing toward the transducer and the trace is becoming damped. The fast-flush only reaches about 90 mmHg.",question:"What is the cause?",options:["Pressure bag under-inflated \u2014 below arterial systolic","Transducer below the axis","Catheter in the vein","Underdamped system"],answer:0,explain:"The flush bag must be at 300 mmHg \u2014 above systolic \u2014 or blood backs up the line, the continuous flush stops and the catheter clots. Inflate the bag to 300 and flush the blood back."},{id:"c-migrated",kind:"fix",level:"Advanced",title:"The CVP that pulses to 25",setup:{scenario:"normal",cvp:"migrated",view:"heart"},brief:"The CVP trace now swings from about 2 to 25 mmHg with every beat, and there are occasional ectopic beats. Freeze the monitor and look at the shape.",question:"What does the waveform show?",options:["The catheter tip has migrated into the right ventricle","Giant v waves from tricuspid regurgitation","Cannon a waves from heart block","An underdamped CVP line"],answer:0,explain:"A sharp systolic rise to \u2248 25 and a diastolic floor near zero is a ventricular trace. TR can give a large c-v wave, but diastolic pressure stays high. Notify the provider and get a chest X-ray; stop vasoactive infusions through that lumen until the tip is confirmed. The provider withdraws it to the cavo-atrial junction; ectopy settles once the tip leaves the RV."},{id:"c-transport",kind:"fix",level:"Advanced",title:"Onto the transport stretcher",setup:{scenario:"sepsis",vent:"ppv",nore:.1,bedH:88,hob:20,below:16,art:"kink",view:"bed"},brief:"You have just moved the patient onto the transport stretcher. The arterial trace looks smudged and MAP reads higher than a minute ago. Norepinephrine 0.1 \xB5g/kg/min is running. Find everything that is wrong before you touch the pump.",question:"Before changing the norepinephrine, what do you suspect?",options:["A monitoring problem: the transducer was not re-levelled and the trace is damped","The septic shock has resolved","The norepinephrine dose is too high","Fluid overload"],answer:0,explain:"A sudden change after moving a patient is a monitoring problem until proven otherwise. The transducer stayed at the old bed height (reading high), and the wrist is flexed, kinking the cannula (damped). Level, straighten the wrist, check with a flush test \u2014 then titrate to the real MAP."},{id:"c-read-tamp",kind:"read",level:"Intermediate",title:"Six hours after cardiac surgery",setup:{scenario:"tamponade",vent:"spont",view:"bed"},brief:"Six hours after valve surgery, the chest drains have stopped draining. Heart rate about 130. Look at both traces with the breathing.",question:"What is the diagnosis?",options:["Cardiac tamponade","Hypovolaemia from bleeding","LV failure","Complete heart block"],answer:0,explain:"High CVP (\u2248 18) with no y descent, a narrow pulse pressure, and systolic falling more than 10 mmHg on each breath in (pulsus paradoxus): tamponade. Hypovolaemia would have a low CVP. Treatment: surgical re-exploration or pericardiocentesis."},{id:"c-read-chb",kind:"read",level:"Intermediate",title:"Slow and strange",setup:{scenario:"chb",view:"bed"},brief:"Heart rate 38. Every so often a very tall wave appears on the CVP trace.",question:"What causes the tall CVP waves?",options:["Cannon a waves: atria contracting against a closed tricuspid (AV dissociation)","Giant v waves of tricuspid regurgitation","Catheter in the right ventricle","Artefact from coughing"],answer:0,explain:"The tall waves are intermittent and fall where an independent P wave lands during ventricular systole: cannon a waves of complete heart block. The slow rate also gives large stroke volumes and a wide pulse pressure."},{id:"c-read-ar",kind:"read",level:"Intermediate",title:"A bounding pulse",setup:{scenario:"ar",view:"bed"},brief:"The arterial trace shows a steep upstroke, a very low diastolic pressure and no clear dicrotic notch.",question:"Which lesion fits?",options:["Aortic regurgitation","Aortic stenosis","Hypovolaemia","Tamponade"],answer:0,explain:"Very wide pulse pressure, low diastolic pressure, steep upstroke and a lost notch (often a bisferiens double peak): aortic regurgitation. AS is the opposite \u2014 slow, small and late."},{id:"c-read-as",kind:"read",level:"Intermediate",title:"Slow to rise",setup:{scenario:"as",view:"bed"},brief:"An elderly patient with a systolic murmur. The arterial upstroke is slow, with a shoulder on the way up, and peaks late.",question:"Which lesion fits?",options:["Aortic stenosis","Aortic regurgitation","Septic shock","Stiff arteries only"],answer:0,explain:"Pulsus parvus et tardus \u2014 a small, late, slow-rising pulse with an anacrotic shoulder \u2014 is aortic stenosis."},{id:"c-ppv-af",kind:"read",level:"Advanced",title:"Is she fluid-responsive?",setup:{scenario:"af",vent:"ppv",view:"bed"},brief:"Ventilated, MAP 80. The monitor shows a pulse-pressure variation over 30 %. The team suggests a fluid bolus.",question:"What do you make of the PPV?",options:["It cannot be used: the rhythm is irregular (AF)","Over 13 % \u2014 give fluid","Over 13 % \u2014 start a vasopressor","It proves she is overloaded"],answer:0,explain:"PPV needs a regular rhythm: in AF every beat has a different filling time, so the pulse pressure varies whatever the volume status. Use a passive leg raise or a fluid challenge with a cardiac-output measure instead."},{id:"c-goal-fluid",kind:"goal",level:"Intermediate",title:"Resuscitate the bleeding patient",setup:{scenario:"hypovol",vent:"ppv",vt:8,view:"bed"},brief:"Haemorrhage, now controlled. Ventilated at 8 mL/kg, sinus tachycardia. Use the waveform to guide fluid.",question:"Is this patient likely to respond to fluid?",options:["Yes \u2014 PPV > 13 % on controlled ventilation in sinus rhythm","No \u2014 the CVP is low","Cannot tell without a cuff pressure","No \u2014 the MAP is 65"],answer:0,explain:"All the conditions for PPV are met and it is well above 13 %. Give fluid in 500 mL steps and re-check the variation after each.",goals:[{label:"PPV below 12 %",test:e=>e.num.ppv!=null&&e.num.ppv<12},{label:"MAP \u2265 65 (true)",test:e=>e.num.tMap>=65}]},{id:"c-goal-sepsis",kind:"goal",level:"Advanced",title:"Warm, vasodilated and hypotensive",setup:{scenario:"sepsis",vent:"ppv",vt:8,view:"bed"},brief:"Septic shock after 2 L of fluid. MAP in the high 50s, low diastolic, low dicrotic notch.",question:"What does the waveform suggest is the main problem?",options:["Low vascular tone \u2014 a vasopressor is needed","Pump failure \u2014 start an inotrope","Severe hypovolaemia only","Tamponade"],answer:0,explain:"Low diastolic pressure with a notch near the diastolic level and a high heart rate: vasoplegia. Norepinephrine restores tone. PPV is still just above 13 %, so some fluid may help alongside it.",goals:[{label:"MAP \u2265 65 (true)",test:e=>e.num.tMap>=65},{label:"MAP \u2264 90",test:e=>e.num.tMap<=90},{label:"Monitoring system correct",test:G}]}];var h={};for(let e of O)for(let t of e.timelines)h[t.id]=t.title;for(let e of[...N,...D,...V,...R])h[e.id]=e.title;for(let e of[...W,...z,I])h[e.id]=e.title;for(let e of _)h[`vent-${e.id}`]=e.title;for(let e of j)h[`lab-${e.id}`]=e.story.split(".")[0];for(let e of K)h[`lines-${e.id}`]=e.title;for(let e of L)h[`abg-${e.id}`]=e.name;for(let e of H)h[e.id]=e.title;for(let e of C)h[`atlas-${e.id}`]=e.title;var Qe=e=>h[e]??e;export{N as a,D as b,V as c,R as d,ce as e,me as f,be as g,ge as h,m as i,c as j,W as k,M as l,q as m,Ae as n,z as o,_ as p,j as q,Ne as r,K as s,Qe as t};
